'use strict';
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),finePointer=matchMedia('(hover: hover) and (pointer: fine)');
let paused=reduced.matches;
const motionButton=document.getElementById('motion-toggle');
function setMotion(value){paused=value;document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Enable animations':'Pause animations';if(paused)document.querySelectorAll('.magnetic,.tilt').forEach(el=>el.style.transform='');}
setMotion(paused);motionButton.addEventListener('click',()=>setMotion(!paused));reduced.addEventListener('change',e=>setMotion(e.matches));setTimeout(()=>document.querySelector('.loader')?.remove(),1900);
const menu=document.querySelector('.menu-button'),nav=document.getElementById('nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu();});
if('IntersectionObserver' in window){document.documentElement.classList.add('js-motion');const reveals=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');reveals.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>reveals.observe(el));const stats=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;stats.unobserve(entry.target);if(paused)return;const start=performance.now(),counters=entry.target.querySelectorAll('[data-count]');function tick(now){const t=paused?1:Math.min((now-start)/1100,1);counters.forEach(el=>el.textContent=Math.round(Number(el.dataset.count)*(1-Math.pow(1-t,3))));if(t<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);}),{threshold:.4});stats.observe(document.querySelector('.stats'));const sections=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;nav.querySelectorAll('a:not(.button)').forEach(a=>{if(a.getAttribute('href')==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}),{rootMargin:'-15% 0px -55% 0px',threshold:0});document.querySelectorAll('main>section[id]').forEach(el=>sections.observe(el));}
let pending=false;const hero=document.querySelector('.hero'),photo=document.querySelector('.hero-photo');function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=(max>0?scrollY/max*100:0)+'%';if(!paused&&finePointer.matches&&hero.getBoundingClientRect().bottom>0)photo.style.transform=`scale(1.06) translateY(${Math.min(scrollY*.12,85)}px)`;pending=false;}addEventListener('scroll',()=>{if(!pending){requestAnimationFrame(updateScroll);pending=true;}},{passive:true});updateScroll();document.querySelectorAll('.magnetic,.tilt').forEach(el=>{el.addEventListener('pointermove',e=>{if(paused||!finePointer.matches)return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=el.classList.contains('tilt')?`perspective(1200px) rotateX(${-y*3}deg) rotateY(${x*3}deg)`:`translate(${x*7}px,${y*7}px)`;});el.addEventListener('pointerleave',()=>el.style.transform='');el.addEventListener('focusout',()=>el.style.transform='');});document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.classList.add('image-failed');img.parentElement.style.backgroundColor='#d8ddc9';}));
const now=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),part=t=>parts.find(p=>p.type===t).value;
document.getElementById('date').min=`${part('year')}-${part('month')}-${part('day')}`;document.getElementById('year').textContent=now.getFullYear();const form=document.getElementById('appointment-form'),status=document.getElementById('form-status'),ready=document.getElementById('whatsapp-ready');form.addEventListener('input',()=>{ready.hidden=true;ready.removeAttribute('href');status.textContent='';});form.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('name');name.setCustomValidity(name.value.trim()?'':'Please enter your name.');if(!form.reportValidity())return;const data=new FormData(form),date=String(data.get('date')||'To be discussed'),message=`Hello Ayushman Ayurvedic Center, I would like to enquire about an appointment.\nName: ${String(data.get('name')).trim()}\nPhone: ${data.get('phone')}\nInterested in: ${data.get('service')}\nPreferred date: ${date}\nPlease confirm availability. Thank you.`;ready.href='https://wa.me/919821816677?text='+encodeURIComponent(message);ready.hidden=false;status.textContent='Your enquiry is ready. Use the link below to review and send it on WhatsApp. Nothing has been sent yet.';ready.focus();});document.getElementById('name').addEventListener('input',e=>e.target.setCustomValidity(''));document.getElementById('load-map').addEventListener('click',()=>{const iframe=document.createElement('iframe');iframe.title='Google Map of Ganjam Street, Kakinada; use directions for the clinic address';iframe.src='https://maps.google.com/maps?q='+encodeURIComponent('D. No. 25-6-24, Ganjam Street, Kakinada, Andhra Pradesh')+'&z=16&output=embed';iframe.loading='lazy';iframe.referrerPolicy='no-referrer-when-downgrade';iframe.allowFullscreen=true;document.getElementById('map-shell').replaceChildren(iframe);iframe.focus();});
